// Hisn al-Muslim generated by scripts/convert-muslim-fortress.mjs.
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import type { ZikrCategory } from "@/lib/data";

export type HisnChapter = { n: number; title: string; items: ZikrCategory["items"]; footnotes: string[] };

export const getHisnChapters = cache(
  async (): Promise<HisnChapter[]> =>
    JSON.parse(await fs.readFile(path.join(process.cwd(), "data/muslim-fortress/chapters.json"), "utf8")),
);
